{"content": "{
  "main_characters": [
    {
      "name": "许长安",
      "role": "protagonist",
      "identity": "城市图书馆临时管理员，25岁，租住在老旧小区的单身青年",
      "traits": ["怕死但冷静", "观察力极强", "嘴贱话痨", "表面怂实则执拗", "野路子逻辑鬼才"],
