tool_call_list.arguments:
{"content": "{
  "main_characters": [
    {
      "name": "许长安",
      "role": "protagonist",
      "identity": "城市图书馆临时管理员，25岁，租住在老旧小区的单身青年",
      "traits": ["怕死但冷静", "观察力极强", "嘴贱话痨", "表面怂实则执拗", "野路子逻辑鬼才"],
      "overt_motivation": "活着从每个副本离开，回归正常生活，继续躺平",
      "covert_motivation": "证明自己不是一个一事无成的废物——他逃避现实的'躺平'其实是对自我价值的恐惧",
      "secret_fear": "害怕在真正需要他的时刻，他会因为怯懦而选择逃跑，然后一辈子活在'我本可以'的后悔中",
      "misperception_of_other": "认为沈夜霜是个冷血无情的通关机器，不理解她为什么总是主动冲在最前面",
      "hidden_connection": "他的母亲许芸十二年前失踪，其实是第一批被拉入异域的'先驱者'之一，织网者选中他并非偶然"
    },
    {
      "name": "沈夜霜",
      "role": "deuteragonist",
      "identity": "资深异域探索者，化名'七号'，真实身份是织网者组织的叛逃者，27岁",
      "traits": ["行动果决", "情感压抑", "缜密多疑", "外冷内疚"],
      "overt_motivation": "摧毁织网者组织，终结异域游戏",
      "covert_motivation": "赎罪——她曾是织网者的执行者，亲手将无辜者送入副本，她需要通过拯救别人来抵消罪恶感",
      "secret_fear": "害怕许长安知道真相后会用那种失望的眼神看她——那意味着她永远不可能被原谅",
      "misperception_of_other": "认为许长安只是个运气好的普通人，最初接近他只是为了利用他身上与织网者的关联",
      "hidden_connection": "她当年执行的第一个任务，就是将许长安的母亲许芸送入了异域"
    }
  ],
  "supporting_characters": [
    {
      "name": "姜铜",
      "function": "助力",
      "identity": "前急诊科医生，35岁，异域中的'老油条'，已通关十余次副本",
      "description": "许长安在第一个副本中遇到的搭档。表面玩世不恭，实际极度谨慎。他有一套自己的生存哲学——'活人比死人有用'。医学知识在副本中多次派上用场。他有个不为人知的秘密：他留在异域不肯离开，是因为他的妻子钟薇在某个副本中失踪，他相信她还活在某个副本深处。助力方式有局限——他的判断偏向保守，遇到需要冒险的关键时刻会犹豫，与许长安形成互补。"
    },
    {
      "name": "傅知行",
      "function": "反转点",
      "identity": "大学哲学系讲师，30岁，戴金丝眼镜，温文尔雅",
      "description": "在第三个副本'末班列车'中加入队伍。博学多才、逻辑缜密，对规则的理解有独到见解。他总是能在关键时刻提出第三种选择，让所有人豁然开朗。然而他的真实身份是织网者安插在玩家中的'观察员'——他的任务是评估许长安是否是织网者需要的'终局之钥'。他对许长安产生了真实的友谊，这让他在最终的忠诚选择中陷入极度痛苦。反转发生在第二幕末尾——他暴露身份，但选择帮助许长安而非织网者。"
    },
    {
      "name": "钟薇",
      "function": "反转点",
      "identity": "姜铜的妻子，原职业为建筑设计师，32岁",
      "description": "在'倒影都市'副本中被找到。她已在异域中独自生存了三年，对副本规则的理解极其深入，甚至发展出了独特的'规则感知'能力。她的出现为主角团提供了关键情报——异域的规则不是天然存在的，而是由织网者人为编写的，每条规则都对应一个现实世界的'锚点'。但她已经不再是姜铜记忆中的那个人，长期隔绝让她变得冷酷而实用主义，这对姜铜造成巨大打击。"
    },
    {
      "name": "卫燃",
      "function": "阻碍",
      "identity": "前特种兵，28岁，异域中的'猎人'型玩家",
      "description": "信奉'弱肉强食'的生存法则，在副本中以掠夺其他玩家资源为生。他不是单纯的反派——他的逻辑在异域的极端环境下有其合理性。他与许长安在'棋盘城'副本中正面对抗，后来在'倒影都市'中被迫合作。他代表了许长安可能走上的另一条路——如果放弃善良和底线，确实能活得更容易。他最终死于织网者的清洗行动，死前将关键情报传给许长安。"
    },
    {
      "name": "许芸",
      "function": "反转点",
      "identity": "许长安的母亲，原职业为中学语文教师，失踪时37岁",
      "description": "十二年前在一次'规则入侵'事件中被拉入异域，是第一代异域探索者。她在异域中发现了织网者的核心秘密——异域不是游戏，而是一种'筛选'机制，目的是找到能改写规则的人。她将这个发现编码隐藏在各个副本的规则漏洞中，留给未来可能进入异域的儿子。许长安一直以为发现的'规则漏洞'是自己的聪明才智，实际上很多是母亲留下的路标。她的最终命运在终局揭晓。"
    },
    {
      "name": "裴见深",
      "function": "阻碍",
      "identity": "织网者组织的核心领袖，外表为40岁左右的儒雅男子，真实年龄不明",
      "description": "异域游戏的总设计师。他并非典型的邪恶反派——他创造异域是因为他发现了现实世界正在'崩解'的证据（规则裂缝），他相信只有通过异域筛选出'规则改写者'，才能修补现实。他的逻辑自洽但手段残忍——为了'大多数人的未来'牺牲少数人。他对许长安有一种近乎偏执的期待，因为许芸是他当年最看好的候选人，而许长安继承了母亲的天赋。最终对决不是武力，而是一场规则层面的博弈。"
    }
  ],
  "relationship_dynamics": "【许长安-沈夜霜】初期：互相利用的被迫同盟（许长安需要沈夜霜的经验，沈夜霜需要许长安身上的织网者关联）→ 中期：经历生死后建立真实信任，许长安开始理解她'冲在前面'不是冷血而是赎罪 → 危机：许长安发现沈夜霜就是当年送走他母亲的人，信任崩塌 → 终局：许长安理解了她的赎罪之心，选择原谅，两人并肩面对最终博弈。关系转折点与大纲呼应：信任建立→第一幕末；信任崩塌→第二幕高潮；和解→第三幕。\n\n【许长安-姜铜】姜铜是许长安在异域中的第一个'大哥'，教会他基本生存法则。两人关系像不靠谱的师兄弟——互相嘴炮但关键时刻绝对互相掩护。姜铜找到妻子钟薇后性情大变（发现妻子已经变了一个人），许长安反过来成为姜铜的精神支柱。\n\n【许长安-傅知行】知己型友谊。傅知行是唯一能跟许长安在智力上平等对话的人，两人经常在副本中展开'规则辩论'。傅知行身份暴露后，是全书最大的情感冲击之一——许长安必须面对'最理解我的人其实一直在观察我'的残酷事实。\n\n【许长安-卫燃】镜像对手。卫燃代表的是'不择手段求生'的路线，许长安代表'底线求生'的路线。两人从敌对到被迫合作，卫燃之死让许长安意识到：在异域中保持善良是一种奢侈，但也是唯一值得坚持的事。\n\n【许长安-许芸-裴见深】三角宿命。许芸是连接一切的枢纽——她是许长安的母亲、沈夜霜的原罪、裴见深的遗憾。许长安追寻母亲的痕迹，实际上是在走母亲十二年前走过的路。终局的选择也与母亲当年面临的选择形成呼应。\n\n【沈夜霜-裴见深】沈夜霜曾是裴见深最信任的执行者，她的叛逃让裴见深既愤怒又失望。裴见深至今认为沈夜霜只是'没有格局'——看到了个体的痛苦就动摇了对大局的判断。"
}", "path": "characters.json"}

